package za.ac.richfield.smartpantry;

import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import java.time.LocalDate; import java.time.format.DateTimeParseException;
public class IngredientFormActivity extends AppCompatActivity{
    private EditText name,quantity,expiry;private Spinner unit;private DatabaseHelper db;private long id=-1;
    protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_ingredient_form);db=new DatabaseHelper(this);name=findViewById(R.id.nameInput);quantity=findViewById(R.id.quantityInput);expiry=findViewById(R.id.expiryInput);unit=findViewById(R.id.unitInput);String[]units={"unit","g","kg","ml","l"};unit.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,units));id=getIntent().getLongExtra("id",-1);if(id!=-1){((TextView)findViewById(R.id.formTitle)).setText("Edit pantry item");PantryItem p=db.pantry(id);if(p!=null){name.setText(p.name);quantity.setText(String.valueOf(p.quantity));expiry.setText(p.expiry);for(int i=0;i<units.length;i++)if(units[i].equals(p.unit))unit.setSelection(i);}}findViewById(R.id.saveButton).setOnClickListener(v->save());}
    private void save(){String n=name.getText().toString().trim(),q=quantity.getText().toString().trim(),e=expiry.getText().toString().trim();if(n.length()<2){name.setError("Enter at least 2 letters");return;}double amount;try{amount=Double.parseDouble(q);if(amount<=0)throw new NumberFormatException();}catch(NumberFormatException ex){quantity.setError("Enter a quantity greater than zero");return;}if(!e.isEmpty())try{LocalDate.parse(e);}catch(DateTimeParseException ex){expiry.setError("Use YYYY-MM-DD");return;}String u=unit.getSelectedItem().toString();if(id==-1)db.addPantry(n,amount,u,e);else db.updatePantry(id,n,amount,u,e);finish();}
}
